/**
 * AX Project Management by YS ver1.0.8 — Offline Manual Viewer & DOCX Downloader Module
 * Works 100% offline in both multi-file package and single-file Standalone/Canvas mode.
 */
const ManualViewer = {
  docxBase64: "",
  docxFilename: "IOSTAR-PM_v1.2.0_설치가이드_및_운영매뉴얼.docx",
  standaloneManualHtmlB64: "",

      openManualWindow() {
    let win = null;
    const isHttp = typeof window !== "undefined" && window.location && window.location.protocol.startsWith("http");

    // 1차 시도: HTTP 환경이면 manual.html 파일 직접 팝업
    if (isHttp) {
      try {
        win = window.open("manual.html", "wbs_manual_popup", "width=1340,height=920,menubar=no,toolbar=no,location=no,status=no,resizable=yes,scrollbars=yes");
      } catch (e) {
        win = null;
      }
    }

    // 2차 시도: file:// 프로토콜이거나 1차 실패 시 빈 창을 열고 내장 Base64 매뉴얼 HTML을 document.write로 즉시 주입 (404 원천 방지)
    if (!win || win.closed || typeof win.closed === "undefined") {
      try {
        win = window.open("", "wbs_manual_popup", "width=1340,height=920,menubar=no,toolbar=no,location=no,status=no,resizable=yes,scrollbars=yes");
        if (win && win.document) {
          const htmlBytes = Uint8Array.from(atob(this.standaloneManualHtmlB64), c => c.charCodeAt(0));
          const htmlText = new TextDecoder("utf-8").decode(htmlBytes);
          win.document.open();
          win.document.write(htmlText);
          win.document.close();
        }
      } catch (e) {
        console.error("Direct popup document.write failed:", e);
        win = null;
      }
    }

    // 3차 시도: 팝업 자체가 브라우저 설정으로 완벽 차단된 경우 내부 모달로 안전하게 폴백
    if (!win || win.closed || typeof win.closed === "undefined") {
      this.openModal();
      if (typeof showToast === "function") {
        showToast("브라우저 팝업이 차단되어 내부 매뉴얼 모달로 열람합니다. (팝업 허용 시 독립창으로 열립니다)", "info");
      }
    }
  },

  openStandaloneWindow() {
    this.openManualWindow();
  },

  openModal() {
    const modal = document.getElementById("offlineManualModal");
    if (!modal) return;
    const iframe = document.getElementById("offlineManualIframe");
    if (iframe && !iframe.getAttribute("data-loaded")) {
      try {
        const htmlBytes = Uint8Array.from(atob(this.standaloneManualHtmlB64), c => c.charCodeAt(0));
        const htmlText = new TextDecoder("utf-8").decode(htmlBytes);
        iframe.srcdoc = htmlText;
        iframe.setAttribute("data-loaded", "true");
      } catch (e) {
        console.error("Failed to load embedded manual:", e);
      }
    }
    modal.classList.add("active");
  },

  closeModal() {
    const modal = document.getElementById("offlineManualModal");
    if (!modal) return;
    modal.classList.remove("active");
  },

  downloadDocx() {
    try {
      const byteCharacters = atob(this.docxBase64);
      const byteNumbers = new Array(byteCharacters.length);
      for (let i = 0; i < byteCharacters.length; i++) {
        byteNumbers[i] = byteCharacters.charCodeAt(i);
      }
      const byteArray = new Uint8Array(byteNumbers);
      const blob = new Blob([byteArray], {
        type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
      });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = this.docxFilename;
      document.body.appendChild(a);
      a.click();
      setTimeout(() => {
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      }, 250);
      if (typeof showToast === "function") {
        showToast("📥 매뉴얼 Word(.docx) 파일 다운로드가 완료되었습니다.", "success");
      }
    } catch (err) {
      console.error("DOCX download error:", err);
      if (typeof showToast === "function") {
        showToast("매뉴얼 다운로드 실패: " + err.message, "error");
      }
    }
  }
};
window.ManualViewer = ManualViewer;
